<?php require __DIR__.'/config.php'; if(is_installed()){header('Location: login.php');exit;} $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$u=trim($_POST['username']??'');$p=$_POST['password']??'';$c=$_POST['confirm']??'';if(!preg_match('/^[A-Za-z0-9._-]{3,50}$/',$u))$error='Choose a valid username (3–50 letters, numbers, dots, dashes or underscores).';elseif(strlen($p)<10)$error='Use a password of at least 10 characters.';elseif($p!==$c)$error='Passwords do not match.';else{write_json('users',[['id'=>1,'username'=>$u,'name'=>'Administrator','role'=>'admin','password_hash'=>password_hash($p,PASSWORD_DEFAULT),'created_at'=>date('c')]]);publish_data();flash('Administrator created. You can now sign in.');redirect('login.php');}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Ridgefield CMS Setup</title><link rel="stylesheet" href="cms.css"><link rel="stylesheet" href="assets/dynamic-site.css">
</head><body class="auth"><div class="auth-card"><div class="brand">A C A D E M Y<small>RIDGEFIELD CMS</small></div><h1>First-time setup</h1><p>Create the private administrator account for Ridgefield.</p><?php if($error):?><div class="alert error"><?=h($error)?></div><?php endif;?><form method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><label>Username<input name="username" autocomplete="username" required></label><label>Password<input type="password" name="password" autocomplete="new-password" required></label><label>Confirm password<input type="password" name="confirm" autocomplete="new-password" required></label><button class="btn primary">Create administrator</button></form><p class="small">Use HTTPS when the CMS is deployed online.</p></div><script src="assets/dynamic-site.js"></script>
